/// Exactly one attribution row for one funding occurrence.
#[derive(Serialize)]
pub struct PaymentAttribution {
    pub(crate) funding_entry_id: FundingEntryId,
    #[serde(flatten)]
    pub(crate) decision: AttributionDecision,
